repo.visits.py:
"""Visit records."""


class Visit:
    def __init__(self, page, minutes):
        self.page = page
        self.minutes = minutes

    def __repr__(self):
        return "Visit(%r, %r)" % (self.page, self.minutes)


ROWS = [('home', 58), ('docs', 29), ('docs', 23), ('home', 10), ('home', 41), ('docs', 32)]


def load_visits():
    """Yield the stored visits one at a time."""
    for page, minutes in ROWS:
        yield Visit(page, minutes)

repo.podium.py:
"""Top visits by minutes."""


def _take_largest(visits):
    """Remove and return the visit with the largest minutes."""
    best = max(visits, key=lambda x: x.minutes)
    visits.remove(best)
    return best


def podium(visits, places=3):
    """Return the top `places` visits by minutes, largest first. The caller's list is left as it was."""
    top = []
    while visits and len(top) < places:
        top.append(_take_largest(visits))
    return top


def report(visits):
    """Return the podium values, the number of visits and every minutes."""
    return {"podium": [x.minutes for x in podium(visits)], "count": len(visits), "all": [x.minutes for x in visits]}


def page_names(visits):
    """Return the distinct page values, in first-seen order."""
    names = []
    for x in visits:
        if x.page not in names:
            names.append(x.page)
    return names

