from visits import load_visits, ROWS
from podium import podium, report

VALUES = [v for _, v in ROWS]


def test_count():
    assert report(list(load_visits()))["count"] == len(ROWS)


def test_all_values_kept():
    assert report(list(load_visits()))["all"] == VALUES


def test_podium_values():
    top = podium(list(load_visits()))
    assert [x.minutes for x in top] == sorted(VALUES, reverse=True)[:3]


def test_caller_list_unchanged():
    data = list(load_visits())
    podium(data, 2)
    assert [x.minutes for x in data] == VALUES


def test_one_place():
    assert [x.minutes for x in podium(list(load_visits()), 1)] == [max(VALUES)]
